  ('Nat03', '576a01ab-b931-5d2d-8b2a-44f5c885f451', 'Área Boscosa', NULL, 'Polígono', 6372, 'borrador', 'INEGI', 'Uso de Suelo y Vegetación. Serie VII', NULL, '{"titulo": "Área Boscosa", "tipo_geometria": "Polígono", "categoria": "mapabase", "custodio": "INEGI", "contacto_custodio": "Directivo", "fuente_origen": "INEGI,2018", "linaje": "Se elaboró a partir de la serie VI, actualizando la información con base en un análisis de imágenes satelitales geomedianas y el consecuente trabajo en campo, cuyos resultados se sustentan a su vez en ejemplares recolectados y analizados en laboratorio. Además, para obtener el formato continuo que abarca todo el territorio nacional (se representan las Islas Marías, Revillagigedo y Guadalupe) se tomaron como base los conjuntos de datos escala 1:250 000, los cuales fueron ensamblados tras efectuar cuidadosas verificaciones que garantizaran la congruencia y la continuidad de la información. Este proceso se realizó tanto para los elementos poligonales incluyen en el producto.", "denominador_escala": "250000", "sistema_coordenadas": "EPSG:6372 — Mexico ITRF2008 / LCC", "fecha_corte": "2021-01-01", "periodicidad": "Intervalos cada tres a cinco años", "restriccion_uso": "interna"}', 'C04_AreaBoscosa_INEGI_2018', 'Mapa Base', 'NAT', 552),
  ('Nat04', '275fa46b-b7a4-5c32-9e9b-90562de8e110', 'Corrientes de Agua área', NULL, 'Polígono', 6372, 'vigente_publico', 'Instituto Nacional de Estadística y Geografía - INEGI.', 'Conjunto de nacional de información topográfica', NULL, '{"titulo": "Corrientes de Agua área", "tipo_geometria": "Polígono", "categoria": "mapabase", "custodio": "Instituto Nacional de Estadística y Geografía - INEGI.", "contacto_custodio": "Director de Servicios de Información. · atencion.usuarios@inegi.org.mx", "fuente_origen": "INEGI, Conjunto nacional de información topográfica 2024", "linaje": "El Conjunto nacional de información topográfica a escala 1:50 000, 2024, es la continuación de los procesos de actualización establecidos en la metodología de los datos topográficos escala 1:50 000 del año 2023, cuya información de calidad cualitativa corresponde a la completitud de geometrías y atributos, añadiendo a este los campos correspondientes a nombres geográficos. Se emplearon distintas fuentes de datos (tanto insumos como otros datos de apoyo) de las unidades de Estado productoras de información cartográfica pertenecientes al SNIEG, las cuales fueron seleccionadas mediante el control de calidad para su incorporación al Conjunto nacional.", "denominador_escala": "50000", "sistema_coordenadas": "EPSG:6372 — Mexico ITRF2008 / LCC", "fecha_corte": "2024-12-13", "periodicidad": "Anual", "restriccion_uso": "pública"}', 'C04_CorrientesAgua_Area_INEGI_2024', 'Mapa Base', 'NAT', 64),
